const pkiDir = '/data/pki';
const opensslBin = '/usr/bin/openssl';

const rootKeyPath = pkiDir + '/root-ca.key';
const rootCrtPath = pkiDir + '/root-ca.crt';
const issuerKeyPath = pkiDir + '/issuer.key';
const issuerCsrPath = pkiDir + '/issuer.csr';
const issuerCrtPath = pkiDir + '/issuer.crt';
const issuerExtPath = pkiDir + '/issuer-ext.cnf';

fs.mkdirSync(pkiDir, { recursive: true });

function sh(cmd) {
    return cp.execSync(cmd, { cwd: pkiDir, stdio: ['ignore', 'pipe', 'pipe'] });
}

// This container's clock can be far off real-world time (sandboxed demo
// environments sometimes run with a future system date). If notBefore is
// stamped at container "now" and that's in the future relative to a real
// device (e.g. the wallet holder's phone), every verifier rejects the cert
// as "not yet valid" / "used before it is allowed". openssl's req/x509 apps
// have no -not_before flag, so backdate generation with faketime instead:
// notBefore lands in 2020 regardless of container time, with -days sized to
// still reach ~2040 -- valid on any real clock for the life of this demo.
function faketime() {
    try {
        cp.execSync('which faketime', { stdio: 'ignore' });
    } catch (e) {
        sh('apk add --no-cache libfaketime');
    }
    return 'faketime "2020-01-01 00:00:00" ';
}

// did:web with path segments: authority first, then each path segment,
// colon-separated (w3c-ccg did-method-web). The credential's `iss`, the
// did.json this issuer serves, and the certificate's SAN all have to agree,
// so they all derive the identifier here.
function issuerDidFor(baseUrl) {
    const rest = baseUrl.replace(/^[a-z]+:\/\//i, '');
    const authority = rest.split('/')[0];
    const segs = rest.split('/').slice(1).filter(Boolean);
    return 'did:web:' + encodeURIComponent(authority) + (segs.length ? ':' + segs.join(':') : '');
}

function publishPki() {
    const rootCaCertPem = fs.readFileSync(rootCrtPath, 'utf8');
    const issuerCertPem = fs.readFileSync(issuerCrtPath, 'utf8');
    const issuerKeyPem = fs.readFileSync(issuerKeyPath, 'utf8');
    const pki = {
        issuerKeyPem,
        issuerCertPem,
        issuerCertDerB64: new crypto.X509Certificate(issuerCertPem).raw.toString('base64'),
        rootCaCertPem,
        rootCaCertDerB64: new crypto.X509Certificate(rootCaCertPem).raw.toString('base64')
    };
    global.set('pki', pki);
    return pki;
}

// A verifier that resolves this issuer's key from the presented chain checks
// that the leaf NAMES the issuer the credential claims to come from -- a chain
// only proves the root vouched for the certificate, not whose it is. DCS
// matches a SAN URI against `iss`, a SAN DNS name against the identifier's
// authority, or the subject CN exactly
// (backend/internal/auth/oid4vp/sdjwt/keys.go, leafIdentifiesIssuer).
//
// The DID is the SAN that always works: a did:web authority carrying a port
// arrives percent-encoded and decodes to host:port, which no DNS name can
// equal, so a demo reached on http://host:8443 is unverifiable on DNS alone.
// The https base URL and hostname are carried too, for wallets that match
// `iss` as a URL (Paradym rejects a PID whose leaf has no SAN matching it).
//
// The public hostname isn't known at deploy time -- ephemeral Cloudflare Quick
// Tunnel URLs change on every cloudflared restart -- so the deploy-time cert
// carries no SAN and this runs on the first request that arrives through the
// real URL, and again whenever that URL changes. The issuer key is kept, so
// reissuing does not invalidate credentials already issued or the key
// published in did.json.
function ensureIssuerCertFor(baseUrl, force) {
    const did = issuerDidFor(baseUrl);
    const hostname = baseUrl.replace(/^[a-z]+:\/\//i, '').split(/[/:]/)[0];

    if (!force && fs.existsSync(issuerCrtPath)) {
        const current = new crypto.X509Certificate(fs.readFileSync(issuerCrtPath, 'utf8'));
        if (String(current.subjectAltName || '').indexOf('URI:' + did) !== -1) {
            const pki = global.get('pki');
            return (pki && pki.issuerKeyPem) ? pki : publishPki();
        }
    }

    fs.writeFileSync(
        issuerExtPath,
        '[v3_issuer]\nkeyUsage=critical,digitalSignature\n' +
        'subjectAltName=URI:' + did + ',URI:' + baseUrl + ',DNS:' + hostname + '\n'
    );
    if (!fs.existsSync(issuerKeyPath)) {
        sh(`${opensslBin} ecparam -name prime256v1 -genkey -noout -out "${issuerKeyPath}"`);
    }
    sh(
        `${opensslBin} req -new -key "${issuerKeyPath}" -out "${issuerCsrPath}" ` +
        `-subj "/CN=FACIS Demo PID Issuer"`
    );
    sh(
        faketime() + `${opensslBin} x509 -req -in "${issuerCsrPath}" ` +
        `-CA "${rootCrtPath}" -CAkey "${rootKeyPath}" -CAcreateserial ` +
        `-out "${issuerCrtPath}" -days 7300 ` +
        `-extfile "${issuerExtPath}" -extensions v3_issuer`
    );

    const pki = publishPki();
    node.log('pki: issued leaf for ' + did + ' (SAN: ' + new crypto.X509Certificate(pki.issuerCertPem).subjectAltName + ')');
    return pki;
}

global.set('issuerDidFor', issuerDidFor);
global.set('ensureIssuerCertFor', ensureIssuerCertFor);

const haveRootCa = fs.existsSync(rootKeyPath) && fs.existsSync(rootCrtPath);
const haveIssuer = fs.existsSync(issuerKeyPath) && fs.existsSync(issuerCrtPath);

if (!haveRootCa) {
    sh(`${opensslBin} ecparam -name prime256v1 -genkey -noout -out "${rootKeyPath}"`);
    sh(
        faketime() + `${opensslBin} req -x509 -new -key "${rootKeyPath}" -out "${rootCrtPath}" ` +
        `-days 7300 -subj "/CN=FACIS Demo Root CA" ` +
        `-addext "basicConstraints=critical,CA:true"`
    );
    node.log('pki: generated root CA');
} else {
    node.log('pki: root CA already present, skipping');
}

if (!haveIssuer) {
    fs.writeFileSync(issuerExtPath, '[v3_issuer]\nkeyUsage=critical,digitalSignature\n');

    sh(`${opensslBin} ecparam -name prime256v1 -genkey -noout -out "${issuerKeyPath}"`);
    sh(
        `${opensslBin} req -new -key "${issuerKeyPath}" -out "${issuerCsrPath}" ` +
        `-subj "/CN=FACIS Demo PID Issuer"`
    );
    sh(
        faketime() + `${opensslBin} x509 -req -in "${issuerCsrPath}" ` +
        `-CA "${rootCrtPath}" -CAkey "${rootKeyPath}" -CAcreateserial ` +
        `-out "${issuerCrtPath}" -days 7300 ` +
        `-extfile "${issuerExtPath}" -extensions v3_issuer`
    );
    node.log('pki: generated issuer cert (no SAN yet -- ensureIssuerCertFor reissues it once the public URL is known)');
} else {
    node.log('pki: issuer cert already present, skipping');
}

publishPki();

node.status({ fill: 'green', shape: 'dot', text: 'pki ready' });
return null;

const pki = global.get('pki');
let pem;
if (pki && pki.rootCaCertPem) {
    pem = pki.rootCaCertPem;
} else {
    pem = fs.readFileSync('/data/pki/root-ca.crt', 'utf8');
}
msg.statusCode = 200;
msg.headers = { 'content-type': 'application/x-pem-file' };
msg.payload = pem;
return msg;

const pki = global.get('pki');
let pem;
if (pki && pki.issuerCertPem) {
    pem = pki.issuerCertPem;
} else {
    pem = fs.readFileSync('/data/pki/issuer.crt', 'utf8');
}
msg.statusCode = 200;
msg.headers = { 'content-type': 'application/x-pem-file' };
msg.payload = pem;
return msg;

const pki = global.get('pki');
let issuerPem, rootPem;
if (pki && pki.issuerCertPem && pki.rootCaCertPem) {
    issuerPem = pki.issuerCertPem;
    rootPem = pki.rootCaCertPem;
} else {
    issuerPem = fs.readFileSync('/data/pki/issuer.crt', 'utf8');
    rootPem = fs.readFileSync('/data/pki/root-ca.crt', 'utf8');
}
const trimmedIssuer = issuerPem.endsWith('\n') ? issuerPem : issuerPem + '\n';
msg.statusCode = 200;
msg.headers = { 'content-type': 'application/x-pem-file' };
msg.payload = trimmedIssuer + rootPem;
return msg;

// Force a fresh issuer leaf for whatever URL this request arrived through.
// The certificate names the issuer it signs for through its SANs (see the
// "ensure root CA + issuer cert" node, ensureIssuerCertFor, for which SANs and
// why), and the public hostname is only knowable from a real request --
// ephemeral Cloudflare Quick Tunnel URLs change on every cloudflared restart.
// Credential issuance calls the same helper on demand, so this endpoint is the
// manual override: hit it through the URL the wallet will actually use.
// The root CA is untouched, so /pki/root-ca.pem stays a valid trust anchor.
const baseUrl = global.get('getBaseUrl')(msg);
const hostname = baseUrl.replace(/^[a-z]+:\/\//i, '').split(/[/:]/)[0];

const pki = global.get('ensureIssuerCertFor')(baseUrl, true);
const cert = new crypto.X509Certificate(pki.issuerCertPem);

node.status({ fill: 'green', shape: 'dot', text: 'reissued for ' + hostname });

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
    reissued: true,
    baseUrl,
    hostname,
    issuerDid: global.get('issuerDidFor')(baseUrl),
    subjectAltName: cert.subjectAltName
};
return msg;

// This issuer signs its credentials with an x5c chain (see the OpenID4VCI
// tab), so a verifier configured with mechanism x5c never reads this
// endpoint. It publishes the same key as the certificate's, for an operator
// writing a trust entry the other way round, or an auditor checking that
// the DID document, the certificate and the credentials all name one key.
const pki = global.get('pki');
let issuerKeyPem;
if (pki && pki.issuerKeyPem) {
    issuerKeyPem = pki.issuerKeyPem;
} else {
    issuerKeyPem = fs.readFileSync('/data/pki/issuer.key', 'utf8');
}
const publicKey = crypto.createPublicKey(crypto.createPrivateKey(issuerKeyPem));
const jwk = publicKey.export({ format: 'jwk' });
const cleanJwk = { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y };
const kid = crypto.createHash('sha256').update(JSON.stringify(cleanJwk)).digest('base64url');

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = { keys: [{ ...cleanJwk, kid, use: 'sig', alg: 'ES256' }] };
return msg;

// Paradym's SD-JWT VC verifier only supports resolving the issuer's
// signing key via a DID or an x5c chain ("unsupported signing method" is
// its exact error otherwise) -- it does not accept a bare embedded `jwk`
// header. DCS resolves an issuer's key by the mechanism its trust entry
// declares (ADR-31): this issuer is configured as `x5c`, so its key comes
// from the chain the credential presents, verified to /pki/root-ca.pem,
// and the leaf has to name this DID (see the PKI ensure node). The document
// below publishes the same key, so a wallet that resolves did:web over
// HTTPS -- Paradym does -- gets the same answer. See the credential-issuance
// function for where `iss` and the proof-header `kid` are set to this DID.
const baseUrl = global.get('getBaseUrl')(msg);
const hostname = baseUrl.replace(/^[a-z]+:\/\//i, '').split(/[/:]/)[0];
// did:web with path segments: authority first, then each path segment,
// colon-separated (w3c-ccg did-method-web). Resolution therefore targets
// <authority>/<segments>/did.json rather than /.well-known/did.json.
const _rest = baseUrl.replace(/^[a-z]+:\/\//i, '');
const _authority = _rest.split('/')[0];
const _segs = _rest.split('/').slice(1).filter(Boolean);
const did = 'did:web:' + encodeURIComponent(_authority) + (_segs.length ? ':' + _segs.join(':') : '');

const pki = global.get('pki');
let issuerKeyPem;
if (pki && pki.issuerKeyPem) {
    issuerKeyPem = pki.issuerKeyPem;
} else {
    issuerKeyPem = fs.readFileSync('/data/pki/issuer.key', 'utf8');
}
const publicKey = crypto.createPublicKey(crypto.createPrivateKey(issuerKeyPem));
const jwk = publicKey.export({ format: 'jwk' });
const cleanJwk = { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y, alg: 'ES256', use: 'sig' };
const keyId = did + '#key-1';

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/did+ld+json' };
msg.payload = {
    '@context': [
        'https://www.w3.org/ns/did/v1',
        'https://w3id.org/security/suites/jws-2020/v1'
    ],
    id: did,
    verificationMethod: [{
        id: keyId,
        type: 'JsonWebKey2020',
        controller: did,
        publicKeyJwk: cleanJwk
    }],
    assertionMethod: [keyId],
    authentication: [keyId]
};
return msg;
